import{z as l,x as o,o as a,c as p,q as r,j as A,D as E,d as s,s as i,S as n,b as t}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"测试策略：单元、集成与属性","description":"","frontmatter":{"title":"测试策略：单元、集成与属性","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/swe-testing-strategy.md","filePath":"cs/swe-testing-strategy.md","lastUpdated":1791413859000}'),d={name:"cs/swe-testing-strategy.md"};function c(m,e,D,h,C,f){const B=o("Mermaid");return a(),p("div",null,[e[2]||(e[2]=r('<h1 id="测试策略-单元、集成与属性" tabindex="-1">测试策略：单元、集成与属性 <a class="header-anchor" href="#测试策略-单元、集成与属性" aria-label="Permalink to &quot;测试策略：单元、集成与属性&quot;">​</a></h1><div class="epigraph"><p>测试不证明程序正确，它只把「改坏了」的发现时刻从用户手里挪回开发者手里；挪得越早，定位越便宜。</p><footer>—— 据 Beck, Test-Driven Development, 2003；Meszaros, xUnit Test Patterns, 2007 整理</footer></div><p><a href="/cs/sc-case-map">上一课</a>给「数值与科学计算」收束：二次方程、方差、求和、softmax 四案各配一道改写——韦达换除法、Welford 增量、成对与补偿、减最大值——检查链从条件数走到工具链合同。数值正确性的判据钉完了，程序设计课末的<a href="/cs/process-addrspace-tour">进程地址空间一览</a>与「从源到进程」的工具链单元——<a href="/cs/preprocessor-preview">预处理器</a>、<a href="/cs/debugger-breakpoint">调试器与断点</a>、<a href="/cs/build-system">构建系统</a>——写的还是一个人怎样把源码变成进程。本课是「软件工程实践」的第一课，把镜头从单人换到持续变更的代码库：改动不断进来，每一笔都要有人回答「改对了没有」。答案不能靠重读全库，只能靠机器可执行的判据。后面的 git、构建与交付各课，都默认你已经会这三层判据与它们的失败次序。早先的<a href="/cs/test-as-spec">测试作为规格</a>写过测试与规格的关系；本课写三层的分工。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>工具链单元留下的缺口在「变更」二字：调试器假设你已经知道去哪打断点，构建假设依赖图写全了，都不回答「这笔改动破坏了什么」。缺口是：把行为切成机器可判定的判据，使任何一笔改动在分钟内得到红或绿。判据按隔离程度分三层，成本与定位能力互为倒挂：隔离越彻底越快、失败越指得准，但替身出来的世界越不真实；越接近真实环境越可信，但越慢、失败越难归因。策略问题因此不是「选哪一层」，而是三层怎么配比、失败在哪层先停。</p><p><span class="marginnote">「判据」就是把『改对了没有』翻译成机器能自动回答的是/非题。人工 review 只能回答『看起来对不对』，回答不了『一千种输入下还对不对』——这正是三层判据存在的理由。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>单元层把被测对象与其依赖切开：文件系统、网络、时钟换成受控替身，单个测试毫秒级、彼此独立、可并行，失败即指向嫌疑最大的一处。TDD 把次序反过来：先写必然失败的测试，再写实现，红-绿-重构，让判据先于代码存在，而不是事后补一张「全绿」的证明。</p><p>集成层不再替身：真实数据库、真实进程间消息，验证接口契约。单元层各自绿、组合起来坏的语义冲突，只有这一层抓得住。代价是秒到分钟级、失败要靠日志归因，所以数量上要让单元层先筛。</p><p>属性层不写具体例子，写两条声明：输入怎么生成（生成器），任何合法输入必须满足什么不变量。引擎随机生成、遇反例缩小成最小反例。反转两次等于自身、序列化再反序列化等于原值，这类对全体输入成立的性质，手写例子覆盖不到的角落正是随机生成器的主场。</p><p><span class="marginnote">Claessen 与 Hughes 2000 年的 QuickCheck 论文把「生成器、不变量、缩小反例」三件套定成属性测试的骨架；shrink 把上千元素的随机失败压到两三个元素的最小反例，这一步的可诊断性是它与朴素随机测试的分界。</span></p>',11)),(a(),A(n,null,{default:E(()=>[i(B,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CHANGE%5B%22%E4%B8%80%E7%AC%94%E5%8F%98%E6%9B%B4%22%5D%20--%3E%20UNIT%5B%22%E5%8D%95%E5%85%83%E5%B1%82%EF%BC%9A%E6%AF%AB%E7%A7%92%E7%BA%A7%EF%BC%8C%E5%A4%B1%E8%B4%A5%E5%8D%B3%E5%81%9C%22%5D%0A%20%20UNIT%20--%3E%20INTEG%5B%22%E9%9B%86%E6%88%90%E5%B1%82%EF%BC%9A%E7%9C%9F%E5%AE%9E%E5%A5%91%E7%BA%A6%EF%BC%8C%E6%85%A2%E8%80%8C%E5%8F%AF%E4%BF%A1%22%5D%0A%20%20INTEG%20--%3E%20PROP%5B%22%E5%B1%9E%E6%80%A7%E5%B1%82%EF%BC%9A%E7%94%9F%E6%88%90%E5%99%A8%E6%8C%81%E7%BB%AD%E6%89%BE%E5%8F%8D%E4%BE%8B%22%5D%0A%20%20PROP%20--%3E%20FIX%5B%22%E6%9C%80%E5%B0%8F%E5%8F%8D%E4%BE%8B%E5%9B%9E%E5%A1%AB%E4%B8%BA%E5%9B%BA%E5%AE%9A%E7%94%A8%E4%BE%8B%22%5D%0A%20%20FIX%20--%3E%20CHANGE%0A"})]),fallback:E(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=t("h2",{id:"机制",tabindex:"-1"},[s("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=t("p",null,"分层有效的机理在反馈环时间决定行为。若全是集成测试，一轮全量小时级，开发者就攒一批改动再跑——失败归因从「一个测试」退化成「一百笔改动」。单元层把归因空间切小：红的单元直接圈出嫌疑；集成层只在单元层放行后的少数嫌疑里仲裁组合错误；属性层则持续抽样。三者不是重要性排序，而是响应速度排序：越快越多，越慢越少。",-1)),(a(),A(n,null,{default:E(()=>[i(B,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%85%A8%E6%98%AF%E9%9B%86%E6%88%90%E6%B5%8B%E8%AF%95%EF%BC%9A%E4%B8%80%E8%BD%AE%E5%B0%8F%E6%97%B6%E7%BA%A7%22%5D%20--%3E%20B%5B%22%E5%BC%80%E5%8F%91%E8%80%85%E6%94%92%E4%B8%80%E5%A4%A9%E6%94%B9%E5%8A%A8%E5%86%8D%E8%B7%91%22%5D%0A%20%20B%20--%3E%20C%5B%22%E5%A4%B1%E8%B4%A5%E5%BD%92%E5%9B%A0%EF%BC%9A%E5%9C%A8%E4%B8%80%E7%99%BE%E7%AC%94%E6%94%B9%E5%8A%A8%E9%87%8C%E6%8D%9E%22%5D%0A%20%20D%5B%22%E5%8D%95%E5%85%83%E5%B1%82%E5%85%88%E7%AD%9B%EF%BC%9A%E6%AF%AB%E7%A7%92%E7%BA%A7%22%5D%20--%3E%20E%5B%22%E7%BA%A2%E7%9A%84%E5%8D%95%E5%85%83%E7%9B%B4%E6%8E%A5%E5%9C%88%E5%87%BA%E5%AB%8C%E7%96%91%22%5D%0A%20%20E%20--%3E%20F%5B%22%E9%9B%86%E6%88%90%E5%B1%82%E5%8F%AA%E5%9C%A8%E5%B0%91%E6%95%B0%E5%AB%8C%E7%96%91%E9%87%8C%E4%BB%B2%E8%A3%81%E7%BB%84%E5%90%88%E9%94%99%22%5D%0A%20%20F%20--%3E%20G%5B%22%E5%B1%9E%E6%80%A7%E5%B1%82%E5%90%8E%E5%8F%B0%E6%8C%81%E7%BB%AD%E6%8A%BD%E5%8F%8D%E4%BE%8B%22%5D%0A"})]),fallback:E(()=>[...e[1]||(e[1]=[s(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=r('<p><span class="marginnote">反馈环的账很好算：两百条单元测试五秒跑完，开发者愿意每保存一次就跑一轮；集成一轮四十分钟，就会攒到下班前才跑。等待时间一旦越过「泡杯咖啡」的量级，运行频率就断崖式下降——配比策略本质是在买运行频率。</span></p><p>测试是抽样，不是证明：属性层跑一百万个输入，也只是对输入分布的一百万次确认，找不到反例只提高置信度。证明属于形式化验证；把「全绿」读成「正确」，是测试策略里最贵的误读。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>覆盖率不是充分性：百分之百行覆盖可以零断言。替身过度会把测试锁在实现上而非行为上——替身越拟真、断言越细，重构越容易翻红，这是 Meszaros 替身谱系里专门的失败模式。属性测试的前提是想得出不变量；想不出时它退化为随机例子。并发与分布式一致性不归三层判据管（<a href="/cs/jepsen-testing">Jepsen</a>）；对二进制与输入空间的随机化搜索是 fuzzing（<a href="/cs/coverage-guided-fuzzing">覆盖引导 fuzzing</a>），同属「机器找反例」。</p><p><span class="marginnote">初学者容易把 100% 覆盖率当绿灯。行覆盖只回答「这行跑过没有」，不回答「结果对不对」——一行断言不写也能满覆盖。覆盖率适合当「哪里没测到」的探测器，不适合当「测够了」的证书。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>三层判据按隔离与真实性倒挂，策略是配比与失败次序，不是三选一。</li><li>单元层换依赖为替身，毫秒级、失败即定位；TDD 让判据先于实现存在。</li><li>集成层验证组合契约；单元各自绿不等于组合绿。</li><li>属性层写生成器与不变量，靠缩小反例把随机失败变成可读的最小反例。</li><li>测试是抽样不是证明；覆盖率、替身保真、并发行为各有边界。</li><li>出处：Beck, <em>Test-Driven Development</em>, 2003；Meszaros, <em>xUnit Test Patterns</em>, 2007；Claessen and Hughes, <em>QuickCheck</em>, 2000。</li></ul>',7))])}const g=l(d,[["render",c]]);export{F as __pageData,g as default};
